(() => {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const DAY = 86400000;
  const localDate = (d = new Date()) => { const x = new Date(d); x.setHours(0,0,0,0); return x; };
  const iso = (d) => { const x = new Date(d); x.setMinutes(x.getMinutes() - x.getTimezoneOffset()); return x.toISOString().slice(0,10); };
  const plusDays = (n, start = new Date()) => { const x = localDate(start); x.setDate(x.getDate()+n); return iso(x); };
  const fmtDate = (v, opts = {day:'2-digit',month:'short'}) => v ? new Intl.DateTimeFormat('pt-BR',opts).format(new Date(`${v}T12:00:00`)).replace('.','') : '—';
  const money = (v) => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(Number(v)||0);
  const uid = () => Math.random().toString(36).slice(2,9);
  const demoData = () => ({
    clients:[
      {id:'c1',name:'Marina Lima',phone:'(11) 98841-6230',email:'marina@email.com',last:plusDays(-1),demo:true},
      {id:'c2',name:'Rafael Costa',phone:'(11) 99736-2041',email:'',last:plusDays(-3),demo:true},
      {id:'c3',name:'Ana Paula Souza',phone:'(11) 98120-5936',email:'ana@email.com',last:plusDays(-5),demo:true},
      {id:'c4',name:'Estúdio Traço',phone:'(11) 99214-7840',email:'contato@estudiotraco.com',last:plusDays(-8),demo:true},
      {id:'c5',name:'Bruno Martins',phone:'(11) 98402-4450',email:'',last:plusDays(-11),demo:true}
    ],
    projects:[
      {id:'p1',name:'Bancada de trabalho',kind:'Mobiliário sob medida',client:'Marina Lima',due:plusDays(4),status:'Em produção',value:2850,demo:true},
      {id:'p2',name:'Estante industrial',kind:'Prateleira / estante',client:'Rafael Costa',due:plusDays(7),status:'Em produção',value:1670,demo:true},
      {id:'p3',name:'Guarda-roupa aberto',kind:'Estrutura em aço',client:'Ana Paula Souza',due:plusDays(11),status:'Orçamento',value:3200,demo:true},
      {id:'p4',name:'Reforço de mezanino',kind:'Estrutura metálica',client:'Estúdio Traço',due:plusDays(14),status:'Concluído',value:4900,demo:true},
      {id:'p5',name:'Cama suspensa',kind:'Mobiliário sob medida',client:'Bruno Martins',due:plusDays(16),status:'Orçamento',value:3800,demo:true}
    ],
    events:[
      {id:'e1',title:'Comprar material — bancada',date:plusDays(1),time:'09:00',type:'Lembrete',notes:'Conferir tubo e chapa.'},
      {id:'e2',title:'Entrega — bancada da Marina',date:plusDays(4),time:'14:00',type:'Entrega',notes:'Confirmar horário com cliente.'},
      {id:'e3',title:'Retornar orçamento',date:plusDays(2),time:'16:00',type:'Retorno',notes:'Estante industrial.'},
      {id:'e4',title:'Visita para medidas',date:plusDays(6),time:'10:30',type:'Visita',notes:'Levar trena e caderno.'}
    ],
    transactions:[
      {id:'t1',description:'Sinal — bancada de trabalho',type:'Entrada',date:plusDays(-2),amount:1400,demo:true},
      {id:'t2',description:'Tubos de aço carbono',type:'Saída',date:plusDays(-3),amount:680,demo:true},
      {id:'t3',description:'Pagamento — reforço mezanino',type:'Entrada',date:plusDays(-6),amount:3500,demo:true},
      {id:'t4',description:'Discos de corte e consumíveis',type:'Saída',date:plusDays(-7),amount:245,demo:true},
      {id:'t5',description:'Saldo — estante industrial',type:'Entrada',date:plusDays(-9),amount:1250,demo:true},
      {id:'t6',description:'Gás para solda',type:'Saída',date:plusDays(-12),amount:420,demo:true},
      {id:'t7',description:'Sinal — guarda-roupa aberto',type:'Entrada',date:plusDays(-14),amount:1600,demo:true},
      {id:'t8',description:'Chapas e perfis',type:'Saída',date:plusDays(-18),amount:970,demo:true}
    ],
    portfolio:[
      {id:'v1',title:'Cama suspensa',description:'Estrutura em aço · sob medida',art:'visual-bed',demo:true},
      {id:'v2',title:'Estante de parede',description:'Metal e madeira · sob medida',art:'visual-shelf',demo:true},
      {id:'v3',title:'Guarda-roupa aberto',description:'Estrutura modular · sob medida',art:'visual-wardrobe',demo:true},
      {id:'v4',title:'Bancada de trabalho',description:'Estrutura reforçada · personalizada',art:'visual-table',demo:true}
    ],
    settings:{workshop:'Metal & Forma',whatsapp:'558387564296',region:''},quotes:[]
  });
  const KEY='mf-workshop-v1';
  let db;
  try { db=JSON.parse(localStorage.getItem(KEY)); } catch {}
  if(!db || !db.clients || !db.projects) { db=demoData(); persist(); }
  function persist(){ localStorage.setItem(KEY,JSON.stringify(db)); }
  function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  let toastTimer;
  function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2900);}
  function demoMark(item){return item.demo?' <small class="demo-inline">exemplo</small>':'';}
  function statusClass(s){return s==='Concluído'?'done':s==='Orçamento'?'quote':s==='Aguardando cliente'?'pending':'production';}
  function updateDateLabels(){const now=new Date();const day=new Intl.DateTimeFormat('pt-BR',{weekday:'long'}).format(now);const date=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(now);const e=$('.welcome-row .admin-eyebrow');if(e)e.textContent=`${day.toUpperCase()} · ${date.toUpperCase()} · ROTINA DA OFICINA`;}
  function render(){renderOverview();renderClients();renderProjects();renderFinance();renderAgenda();renderPortfolio();renderSettings();updateDateLabels();}
  function renderOverview(){
    const active=db.projects.filter(p=>p.status==='Em produção').length, quotes=db.projects.filter(p=>p.status==='Orçamento'||p.status==='Aguardando cliente').length;
    $('#metric-active').textContent=String(active).padStart(2,'0');$('#metric-quotes').textContent=String(quotes).padStart(2,'0');
    const month=iso(new Date()).slice(0,7);const income=db.transactions.filter(t=>t.type==='Entrada'&&t.date.startsWith(month)).reduce((a,t)=>a+Number(t.amount),0);$('#metric-income').textContent=money(income);
    const upcoming=db.projects.filter(p=>p.status!=='Concluído'&&p.due).sort((a,b)=>a.due.localeCompare(b.due))[0];$('#metric-next').innerHTML=upcoming?`${new Date(`${upcoming.due}T12:00:00`).getDate()} <small>${new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${upcoming.due}T12:00:00`)).replace('.','').toUpperCase()}</small>`:'—';$('#metric-next-name').textContent=upcoming?upcoming.name:'Sem entregas próximas';
    const recent=[...db.projects].sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4);$('#overview-projects').innerHTML=recent.length?recent.map(p=>`<tr><td><div class="project-name-cell"><span class="project-thumb">⌑</span><span><b>${escapeHTML(p.name)}${demoMark(p)}</b><small>${escapeHTML(p.kind||'Projeto sob medida')}</small></span></div></td><td class="client-cell">${escapeHTML(p.client||'—')}</td><td>${fmtDate(p.due,{day:'2-digit',month:'short'})}</td><td><span class="status-pill ${statusClass(p.status)}">${escapeHTML(p.status)}</span></td><td><button class="row-more" data-project-edit="${p.id}">···</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty-state">Nenhum projeto cadastrado.</div></td></tr>';
    renderMiniCalendar();renderActivity();
  }
  function renderMiniCalendar(){const base=localDate();const monday=new Date(base);monday.setDate(base.getDate()-((base.getDay()+6)%7));const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);$('.agenda-panel .panel-eyebrow').textContent=new Intl.DateTimeFormat('pt-BR',{day:'2-digit'}).format(monday)+' — '+new Intl.DateTimeFormat('pt-BR',{day:'2-digit'}).format(sunday)+' '+new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(sunday).toUpperCase();const labels=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];$('#mini-calendar').innerHTML=labels.map((l,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);const date=iso(d);const today=date===iso(base);const has=db.events.some(e=>e.date===date);return `<div class="mini-day ${today?'is-today':''} ${has?'has-event':''}">${l}<b>${d.getDate()}</b></div>`}).join('');const events=[...db.events].filter(e=>e.date>=iso(base)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,3);$('#agenda-preview').innerHTML=events.length?events.map(e=>`<div class="agenda-item"><span class="agenda-time">${escapeHTML(e.time||'—')}</span><div><b>${escapeHTML(e.title)}</b><small>${fmtDate(e.date,{weekday:'short',day:'numeric',month:'short'})} · ${escapeHTML(e.type||'Lembrete')}</small></div></div>`).join(''):'<div class="empty-state">Agenda livre por enquanto.</div>';$('#agenda-badge').textContent=events.length;}
  function renderActivity(){const actions=[...db.projects].sort((a,b)=>b.due.localeCompare(a.due)).slice(0,3);$('#activity-list').innerHTML=actions.length?actions.map((p,i)=>`<div class="activity-row"><span class="activity-icon">${i===0?'↗':'⌑'}</span><span><b>${escapeHTML(p.name)}${demoMark(p)}</b><small>${p.status==='Concluído'?'Projeto concluído':'Projeto atualizado'} · ${escapeHTML(p.client||'sem cliente')}</small></span><time>${fmtDate(p.due)}</time></div>`).join(''):'<div class="empty-state">Sua atividade aparecerá aqui.</div>';}
  function renderClients(){const term=($('#client-search')?.value||'').toLocaleLowerCase('pt-BR');const clients=db.clients.filter(c=>`${c.name} ${c.phone} ${c.email}`.toLocaleLowerCase('pt-BR').includes(term));$('#clients-table').innerHTML=clients.length?clients.map(c=>{const n=db.projects.filter(p=>p.client===c.name).length;return `<tr><td><div class="project-name-cell"><span class="avatar">${escapeHTML(c.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><span><b>${escapeHTML(c.name)}${demoMark(c)}</b><small>${escapeHTML(c.email||'Cliente')}</small></span></div></td><td>${escapeHTML(c.phone||'—')}</td><td>${n} ${n===1?'projeto':'projetos'}</td><td>${fmtDate(c.last)}</td><td><button class="row-more" data-client-edit="${c.id}">···</button></td></tr>`}).join(''):'<tr><td colspan="5"><div class="empty-state"><b>Nenhum cliente encontrado.</b>Cadastre um cliente para começar.</div></td></tr>';$('#client-count-label').textContent=`${db.clients.length} ${db.clients.length===1?'cliente':'clientes'}`;}
  let projectFilter='Todos';
  function renderProjects(){const term=($('#project-search')?.value||'').toLocaleLowerCase('pt-BR');const rows=db.projects.filter(p=>(projectFilter==='Todos'||p.status===projectFilter)&&`${p.name} ${p.client} ${p.kind}`.toLocaleLowerCase('pt-BR').includes(term));$('#count-all').textContent=db.projects.length;$('#projects-table').innerHTML=rows.length?rows.map(p=>`<tr><td><div class="project-name-cell"><span class="project-thumb">⌑</span><span><b>${escapeHTML(p.name)}${demoMark(p)}</b><small>${escapeHTML(p.kind||'Projeto sob medida')}</small></span></div></td><td>${escapeHTML(p.client||'—')}</td><td>${money(p.value)}</td><td>${fmtDate(p.due)}</td><td><span class="status-pill ${statusClass(p.status)}">${escapeHTML(p.status)}</span></td><td><button class="row-more" data-project-edit="${p.id}">···</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state"><b>Nenhum projeto por aqui.</b>Adicione um projeto ou ajuste os filtros.</div></td></tr>';}
  function renderFinance(){const month=iso(new Date()).slice(0,7);const rows=[...db.transactions].sort((a,b)=>b.date.localeCompare(a.date));const incoming=rows.filter(t=>t.type==='Entrada'&&t.date.startsWith(month)).reduce((s,t)=>s+Number(t.amount),0);const outgoing=rows.filter(t=>t.type==='Saída'&&t.date.startsWith(month)).reduce((s,t)=>s+Number(t.amount),0);$('#finance-in').textContent=money(incoming);$('#finance-out').textContent=money(outgoing);$('#finance-net').textContent=money(incoming-outgoing);$('#transaction-count').textContent=`${rows.length} lançamentos`;
    const monthAll=rows.filter(t=>t.date.startsWith(month));$('#finance-table').innerHTML=(monthAll.length?monthAll:rows).length?(monthAll.length?monthAll:rows).map(t=>`<tr><td><b>${escapeHTML(t.description)}${demoMark(t)}</b></td><td><span class="status-pill ${t.type==='Entrada'?'done':'pending'}">${t.type}</span></td><td>${fmtDate(t.date)}</td><td style="color:${t.type==='Entrada'?'#668052':'#a36d55'};font-weight:700">${t.type==='Entrada'?'+':'−'} ${money(t.amount)}</td><td><button class="row-more" data-transaction-delete="${t.id}">×</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty-state"><b>Sem lançamentos neste mês.</b>Registre entradas e custos para acompanhar seu saldo.</div></td></tr>';}
  let weekOffset=0;
  function renderAgenda(){renderWeek();renderReminders();}
  function renderWeek(){const base=localDate();base.setDate(base.getDate()-((base.getDay()+6)%7)+weekOffset*7);const end=new Date(base);end.setDate(base.getDate()+6);const monthA=new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(base), monthB=new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(end);$('#week-label').textContent=monthA===monthB?`${base.getDate()}–${end.getDate()} ${monthA} ${base.getFullYear()}`:`${base.getDate()} ${monthA} — ${end.getDate()} ${monthB} ${base.getFullYear()}`;
    const heads=Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(base.getDate()+i);return `<div class="week-head ${iso(d)===iso(new Date())?'today':''}">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'][i]}<b>${d.getDate()}</b></div>`}).join('');const hours=['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00'];let grid='<div class="week-head"></div>'+heads;for(const h of hours){grid+=`<div class="time-label">${h}</div>`;for(let i=0;i<7;i++){const d=new Date(base);d.setDate(base.getDate()+i);const date=iso(d);const events=db.events.filter(e=>e.date===date&&(e.time||'09:00').slice(0,2)===h.slice(0,2));grid+=`<div class="calendar-cell">${events.map(e=>`<div class="calendar-event ${e.type==='Entrega'?'production':'reminder'}" title="${escapeHTML(e.title)}" data-event-edit="${e.id}">${escapeHTML(e.title)}</div>`).join('')}</div>`;}}$('#week-calendar').innerHTML=grid;}
  function renderReminders(){const rows=[...db.events].filter(e=>e.date>=iso(new Date())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));$('#reminder-count').textContent=rows.length;$('#reminders-list').innerHTML=rows.length?rows.slice(0,7).map(e=>`<div class="reminder-row"><div class="reminder-date"><b>${new Date(`${e.date}T12:00:00`).getDate()}</b><small>${new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${e.date}T12:00:00`)).replace('.','').toUpperCase()}</small></div><div class="reminder-copy"><b>${escapeHTML(e.title)}</b><small>${escapeHTML(e.time||'—')} · ${escapeHTML(e.type||'Lembrete')}</small></div><button class="row-more" data-event-edit="${e.id}">···</button></div>`).join(''):'<div class="empty-state"><b>Sem lembretes próximos.</b>Sua agenda está livre.</div>';}
  const artMarkup=(art)=>`<div class="project-visual ${escapeHTML(art||'visual-bed')}"><div class="bed-art"><span class="bed-mattress"></span><span class="bed-leg one"></span><span class="bed-leg two"></span><span class="bed-rail"></span></div><div class="shelf-art"><i></i><i></i><i></i><b></b></div><div class="wardrobe-art"><i></i><i></i><b></b></div><div class="table-art"><i></i><b></b><span></span></div></div>`;
  function renderPortfolio(){const host=$('#showcase-grid');host.innerHTML=db.portfolio.map(p=>`<article class="showcase-card"><div class="showcase-thumb">${p.image?`<img src="${p.image}" alt="${escapeHTML(p.title)}">`:artMarkup(p.art)}</div><div class="showcase-info"><b>${escapeHTML(p.title)}${demoMark(p)}</b><small>${escapeHTML(p.description||'Projeto sob medida')}</small><div class="showcase-actions"><button data-portfolio-edit="${p.id}">Editar</button><button data-portfolio-delete="${p.id}">Remover</button></div></div></article>`).join('')||'<div class="empty-state"><b>Seu portfólio está vazio.</b>Adicione fotos dos seus projetos.</div>';}
  function renderSettings(){const f=$('#settings-form');if(!f)return;f.elements.workshop.value=db.settings?.workshop||'';f.elements.whatsapp.value=db.settings?.whatsapp||'';f.elements.region.value=db.settings?.region||'';}
  const tabs=['overview','agenda','clients','projects','finance','showcase','settings'];const tabNames={overview:'Visão geral',agenda:'Agenda',clients:'Clientes',projects:'Projetos',finance:'Financeiro',showcase:'Portfólio',settings:'Configurações'};
  function setTab(tab){if(!tabs.includes(tab))tab='overview';tabs.forEach(t=>$('#tab-'+t)?.classList.toggle('hidden',t!==tab));$$('.side-link').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#current-crumb').textContent=tabNames[tab];if(tab==='settings')renderSettings();history.replaceState(null,'','#painel-'+tab);}
  function openAdmin(){ $('.site-view').classList.add('hidden');$('#admin-view').classList.remove('hidden');setTab('overview');render();window.scrollTo(0,0);}
  function openSite(){ $('#admin-view').classList.add('hidden');$('.site-view').classList.remove('hidden');history.replaceState(null,'','#inicio');window.scrollTo(0,0);}
  $$('.admin-open').forEach(b=>b.addEventListener('click',openAdmin));$('#back-to-site').addEventListener('click',openSite);$$('.side-link').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));document.addEventListener('click',e=>{const x=e.target.closest('[data-tab-jump]');if(x){openAdmin();setTab(x.dataset.tabJump);}});$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.goto)));
  function modalOpen(title,eyebrow,fields,saveText='Salvar'){ $('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-fields').innerHTML=fields;$('#modal-save').textContent=saveText;$('#modal-backdrop').classList.remove('hidden');setTimeout(()=>$('#modal-fields input,#modal-fields select')?.focus(),30); }
  function modalClose(){$('#modal-backdrop').classList.add('hidden');$('#modal-form').onsubmit=null;}
  $('#modal-close').addEventListener('click',modalClose);$('#modal-cancel').addEventListener('click',modalClose);$('#modal-backdrop').addEventListener('click',e=>{if(e.target===$('#modal-backdrop'))modalClose()});document.addEventListener('keydown',e=>{if(e.key==='Escape')modalClose()});
  const field=(label,name,type='text',value='',placeholder='')=>`<label class="modal-field">${label}<input name="${name}" type="${type}" value="${escapeHTML(value)}" placeholder="${escapeHTML(placeholder)}" ${type==='number'?'min="0" step="0.01"':''}></label>`;
  const selectField=(label,name,options,value='')=>`<label class="modal-field">${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${escapeHTML(o)}</option>`).join('')}</select></label>`;
  function newClient(existing){const c=existing||{};modalOpen(existing?'Editar cliente':'Novo cliente','CADASTRO DE CLIENTE',`${field('Nome completo','name','text',c.name||'','Nome do cliente')}${field('WhatsApp','phone','tel',c.phone||'','(00) 00000-0000')}${field('E-mail','email','email',c.email||'','opcional')}`);$('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const val={name:f.get('name').trim(),phone:f.get('phone').trim(),email:f.get('email').trim(),last:iso(new Date()),demo:false};if(!val.name)return;if(c.id)Object.assign(c,val);else db.clients.unshift({id:uid(),...val});persist();render();modalClose();toast(c.id?'Cliente atualizado.':'Cliente cadastrado.');};}
  function newProject(existing){const p=existing||{};modalOpen(existing?'Editar projeto':'Novo projeto','ACOMPANHAMENTO DA PRODUÇÃO',`${field('Nome do projeto','name','text',p.name||'','Ex.: Prateleira para cozinha')}${selectField('Cliente','client',['— Sem cliente —',...db.clients.map(c=>c.name)],p.client||'— Sem cliente —')}${field('Tipo / material','kind','text',p.kind||'','Ex.: Aço carbono · solda MIG')}${field('Valor combinado (R$)','value','number',p.value||'','0')}${field('Data de entrega / retorno','due','date',p.due||plusDays(7))}${selectField('Etapa',['status'][0],['Orçamento','Aguardando cliente','Em produção','Concluído'],p.status||'Orçamento')}`);$('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const val={name:f.get('name').trim(),client:f.get('client')==='— Sem cliente —'?'':f.get('client'),kind:f.get('kind').trim(),value:Number(f.get('value'))||0,due:f.get('due'),status:f.get('status'),demo:false};if(!val.name)return;if(p.id)Object.assign(p,val);else db.projects.unshift({id:uid(),...val});persist();render();modalClose();toast(p.id?'Projeto atualizado.':'Projeto registrado.');};}
  function newEvent(existing){const e0=existing||{};modalOpen(existing?'Editar lembrete':'Novo lembrete','AGENDA DA OFICINA',`${field('O que precisa acontecer?','title','text',e0.title||'','Ex.: Comprar material')}${field('Data','date','date',e0.date||plusDays(1))}${field('Horário','time','time',e0.time||'09:00')}${selectField('Tipo','type',['Lembrete','Entrega','Retorno','Visita'],e0.type||'Lembrete')}<label class="modal-field">Anotações<textarea name="notes" placeholder="Detalhes para lembrar">${escapeHTML(e0.notes||'')}</textarea></label>`);$('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const val={title:f.get('title').trim(),date:f.get('date'),time:f.get('time'),type:f.get('type'),notes:f.get('notes').trim()};if(!val.title)return;if(e0.id)Object.assign(e0,val);else db.events.push({id:uid(),...val});persist();render();modalClose();toast(e0.id?'Lembrete atualizado.':'Lembrete adicionado à agenda.');};}
  function newTransaction(){modalOpen('Novo lançamento','CONTROLE FINANCEIRO',`${field('Descrição','description','text','','Ex.: Compra de material')}${selectField('Tipo','type',['Entrada','Saída'],'Entrada')}${field('Valor (R$)','amount','number','','0')}${field('Data','date','date',iso(new Date()))}`);$('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const val={description:f.get('description').trim(),type:f.get('type'),amount:Number(f.get('amount'))||0,date:f.get('date'),demo:false};if(!val.description||!val.amount){toast('Informe a descrição e o valor.');return;}db.transactions.unshift({id:uid(),...val});persist();render();modalClose();toast('Lançamento registrado.');};}
  function newPortfolio(existing){const p=existing||{};modalOpen(existing?'Editar trabalho':'Adicionar ao portfólio','VITRINE DE PROJETOS',`${field('Nome do trabalho','title','text',p.title||'','Ex.: Estante para sala')}${field('Descrição curta','description','text',p.description||'','Material, estilo ou aplicação')}<label class="modal-field">Foto do projeto<input name="image" type="file" accept="image/png,image/jpeg,image/webp"><small style="display:block;margin-top:5px;color:#90948a;font-weight:400">A imagem ficará salva neste navegador. Escolha fotos com até 1 MB.</small></label>`,'Adicionar trabalho');$('#modal-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const file=f.get('image');let image=p.image||'';if(file&&file.size){if(file.size>1024*1024){toast('A imagem precisa ter até 1 MB para salvar neste navegador.');return;}image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}const val={title:f.get('title').trim(),description:f.get('description').trim(),image,demo:false};if(!val.title)return;if(p.id)Object.assign(p,val);else db.portfolio.unshift({id:uid(),...val});persist();renderPortfolio();modalClose();toast('Portfólio atualizado.');};}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const type=b.dataset.action;if(type==='new-client')newClient();if(type==='new-project')newProject();if(type==='new-event')newEvent();if(type==='new-transaction')newTransaction();if(type==='new-portfolio')newPortfolio();});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-client-edit]');if(b){const c=db.clients.find(x=>x.id===b.dataset.clientEdit);if(c)newClient(c);return;}const p=e.target.closest('[data-project-edit]');if(p){const item=db.projects.find(x=>x.id===p.dataset.projectEdit);if(item)newProject(item);return;}const ev=e.target.closest('[data-event-edit]');if(ev){const item=db.events.find(x=>x.id===ev.dataset.eventEdit);if(item)newEvent(item);return;}const del=e.target.closest('[data-transaction-delete]');if(del){if(confirm('Remover este lançamento?')){db.transactions=db.transactions.filter(x=>x.id!==del.dataset.transactionDelete);persist();render();toast('Lançamento removido.');}return;}const pd=e.target.closest('[data-portfolio-delete]');if(pd){if(confirm('Remover este trabalho do portfólio?')){db.portfolio=db.portfolio.filter(x=>x.id!==pd.dataset.portfolioDelete);persist();renderPortfolio();toast('Trabalho removido.');}return;}const pe=e.target.closest('[data-portfolio-edit]');if(pe){const item=db.portfolio.find(x=>x.id===pe.dataset.portfolioEdit);if(item)newPortfolio(item);}});
  $('#prev-week').addEventListener('click',()=>{weekOffset--;renderWeek()});$('#next-week').addEventListener('click',()=>{weekOffset++;renderWeek()});$('#today-button').addEventListener('click',()=>{weekOffset=0;renderWeek()});$('#client-search').addEventListener('input',renderClients);$('#project-search').addEventListener('input',renderProjects);$('#project-filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;projectFilter=b.dataset.filter;$$('#project-filters button').forEach(x=>x.classList.toggle('selected',x===b));renderProjects();});
  $('#settings-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);db.settings={workshop:f.get('workshop').trim()||'Metal & Forma',whatsapp:f.get('whatsapp').replace(/\D/g,''),region:f.get('region').trim()};persist();toast('Configurações salvas neste navegador.');});
  $('#export-data').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='metal-forma-dados.json';a.click();URL.revokeObjectURL(a.href);toast('Cópia dos dados baixada.');});$('#clear-demo-data').addEventListener('click',()=>{if(confirm('Restaurar os dados de demonstração? Os registros adicionados neste navegador serão apagados.')){db=demoData();persist();render();toast('Dados de demonstração restaurados.');}});
  const projectCategories={'Cama suspensa':'Estrutura de cama','Estante de parede':'Prateleira / estante','Guarda-roupa aberto':'Guarda-roupa / armário','Bancada de trabalho':'Mesa / bancada'};
  $$('.project-request').forEach(b=>b.addEventListener('click',()=>{const projectType=projectCategories[b.dataset.project]||'Outro projeto sob medida';$('#quote-project').value=projectType;const details=$('#quote-form').elements.details;const note=`Tenho interesse no projeto do portfólio: ${b.dataset.project}.`;if(!details.value.includes(note))details.value=details.value.trim()?`${details.value.trim()}\n${note}`:note;$('#orcamento').scrollIntoView({behavior:'smooth'});$('#quote-form').elements.name.focus({preventScroll:true});}));
  $('#quote-files').addEventListener('change',e=>{const files=[...e.target.files].slice(0,5);const bad=files.find(f=>f.size>10*1024*1024);if(bad){e.target.value='';$('#quote-file-count').textContent='0 / 5';$('#quote-file-names').textContent='Uma imagem ultrapassa o limite de 10 MB.';return;}$('#quote-file-count').textContent=`${files.length} / 5`;$('#quote-file-names').textContent=files.map(f=>f.name).join(' · ');});
  $('#quote-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const files=[...$('#quote-files').files].slice(0,5);const q={id:uid(),name:f.get('name').trim(),contact:f.get('contact').trim(),project:f.get('project'),material:f.get('material')||'Ainda não definido',measures:f.get('measures')||'Não informado',timeline:f.get('timeline'),details:f.get('details')||'',photos:files.map(x=>x.name),createdAt:new Date().toISOString()};db.quotes.unshift(q);let client=db.clients.find(c=>c.phone.replace(/\D/g,'')===q.contact.replace(/\D/g,''));if(!client){client={id:uid(),name:q.name,phone:q.contact,email:'',last:iso(new Date()),demo:false};db.clients.unshift(client);}else{client.last=iso(new Date());}db.projects.unshift({id:uid(),name:q.project,kind:q.material,due:plusDays(7),status:'Orçamento',value:0,demo:false,client:q.name,quoteId:q.id,photoNames:q.photos});persist();if(!$('#admin-view').classList.contains('hidden'))render();const lines=[`Olá! Meu nome é ${q.name}.`, '',`Gostaria de pedir um orçamento para: ${q.project}.`,`Material / solda: ${q.material}.`,`Medidas: ${q.measures}.`,`Prazo desejado: ${q.timeline}.`,`Meu WhatsApp para retorno: ${q.contact}.`];if(q.details)lines.push('',`Mais detalhes: ${q.details}`);if(files.length)lines.push('',`Tenho ${files.length} foto(s) de referência (${files.map(x=>x.name).join(', ')}). Vou anexar na conversa.`);const msg=encodeURIComponent(lines.join('\n'));const phone=(db.settings?.whatsapp||'').replace(/\D/g,'');const feed=$('#quote-feedback');if(phone.length>=12){window.open(`https://wa.me/${phone}?text=${msg}`,'_blank','noopener');feed.textContent='Resumo preparado. Anexe as imagens selecionadas na conversa do WhatsApp.';}else{feed.textContent='Solicitação registrada neste navegador. Configure o WhatsApp da oficina no painel para abrir a conversa automaticamente.';toast('Configure o WhatsApp da oficina no painel para receber pedidos.');}e.currentTarget.reset();$('#quote-file-count').textContent='0 / 5';$('#quote-file-names').textContent='';});
  $('#settings-form').addEventListener('input',e=>{if(e.target.name==='whatsapp')e.target.value=e.target.value.replace(/[^\d+ ()-]/g,'').slice(0,22)});
  $$('.menu-toggle').forEach(b=>b.addEventListener('click',()=>$('.main-nav').classList.toggle('open')));$$('.main-nav a').forEach(a=>a.addEventListener('click',()=>$('.main-nav').classList.remove('open')));
  if(location.hash.startsWith('#painel-')){openAdmin();setTab(location.hash.slice(8));}render();
})();
